<script setup lang="ts">
import {ref} from 'vue';import YkSelect from '../../components/common/YkSelect.vue';import {api,type ApiError} from '../api'
const pollType=ref('UNDERSTANDING'),message=ref(''),results=ref<{label:string;count:number}[]>([]);const modes=[{value:'UNDERSTANDING',label:'理解度投票'},{value:'ASSIGNMENT_COMPLETION',label:'作业完成情况'},{value:'TEACHING_FEEDBACK',label:'教学反馈'}]
async function publishPoll(){try{const labels=pollType.value==='UNDERSTANDING'?['完全掌握','基本掌握','需要复习']:pollType.value==='ASSIGNMENT_COMPLETION'?['已完成','进行中','未开始']:['很好','一般','需改进'];const poll=await api<{poll_id:string;options:{option_id:string}[]}>('/api/v1/polls',{method:'POST',body:JSON.stringify({course_id:localStorage.getItem('yk-course-id'),class_id:localStorage.getItem('yk-class-id'),poll_type:pollType.value,title:'RSA 课堂反馈',options:labels})});await api(`/api/v1/polls/${poll.poll_id}/publish`,{method:'POST'});localStorage.setItem('yk-poll-id',poll.poll_id);localStorage.setItem('yk-poll-option-id',poll.options[0].option_id);message.value='投票已发布'}catch(e){message.value=(e as ApiError).message}}
async function publishWork(){try{const common={course_id:localStorage.getItem('yk-course-id'),class_id:localStorage.getItem('yk-class-id'),title:'RSA 课后作业',questions:[{question_id:'question-b-rsa-1',question_version:'v1',question_snapshot:{stem:'RSA 算法中公开的是哪一类密钥？'},max_score:10}]};const assignment=await api<{assignment_id:string}>('/api/v1/assignments',{method:'POST',body:JSON.stringify({...common,due_at:new Date(Date.now()+86400000).toISOString().replace('Z',''),random_order:true})});await api(`/api/v1/assignments/${assignment.assignment_id}/publish`,{method:'POST'});const quiz=await api<{quiz_id:string}>('/api/v1/quizzes',{method:'POST',body:JSON.stringify({...common,title:'RSA 课堂小测',time_limit_minutes:10,random_order:true})});await api(`/api/v1/quizzes/${quiz.quiz_id}/publish`,{method:'POST'});localStorage.setItem('yk-assignment-id',assignment.assignment_id);localStorage.setItem('yk-quiz-id',quiz.quiz_id);message.value='作业与测验已发布'}catch(e){message.value=(e as ApiError).message}}
async function loadResults(){const id=localStorage.getItem('yk-poll-id');if(id)results.value=(await api<{items:{label:string;count:number}[]}>(`/api/v1/polls/${id}/results`)).items}
</script>
<template><div><div class="hero"><div><h1>作业与测验</h1><p>复用题库标识，发布时冻结题目版本快照。</p></div><button class="yk-button primary" @click="publishWork">＋ 发布课后作业与小测</button></div><p v-if="message" data-testid="work-message" class="status-ok">{{message}}</p><div class="grid grid-2"><section class="card"><div class="section-head"><h3>在线投票</h3><span class="badge">三种模式</span></div><label class="yk-field"><span>投票方式</span><YkSelect v-model="pollType" :options="modes"/></label><div class="actions" style="margin-top:12px"><button class="yk-button primary" @click="publishPoll">发布投票</button><button class="yk-button" @click="loadResults">查看统计</button></div><div v-for="row in results" :key="row.label" class="poll-result"><span>{{row.label}}</span><b>{{row.count}} 人</b></div></section><section class="card"><h3>第 12 课时 · RSA 作业</h3><div class="card"><b>单选题</b><p>RSA 算法中用于公开给通信对方的是哪一类密钥？</p></div><p class="muted">发布班级：网络安全 2301 班<br>题目顺序：学生随机<br>课堂小测：4 题 · 10 分钟</p></section></div></div></template>
